def transform(grid):
    h, w = len(grid), len(grid[0])
    base = [row[::-1] for row in grid[::-1]]
    out = []
    for y in range(3 * h):
        tile_y, local_y = divmod(y, h)
        if tile_y == 1:
            local_y = h - 1 - local_y
        row = []
        for x in range(2 * w):
            tile_x, local_x = divmod(x, w)
            if tile_x == 1:
                local_x = w - 1 - local_x
            row.append(base[local_y][local_x])
        out.append(row)
    return out
